package com.xuhang.mealops.inventory.domain;
import static org.assertj.core.api.Assertions.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.*; import org.junit.jupiter.api.Test; import com.xuhang.mealops.measurement.domain.*;
class InventoryConsumptionAllocatorTest { private InventoryBatch b(long id,String amount,Unit u,LocalDate d){return InventoryBatch.reconstitute(id,1,Quantity.of(new BigDecimal(amount),u),d,0);} @Test void allocatesFefoEvenWhenInputUnsorted(){var p=new InventoryConsumptionAllocator().allocate(1,Quantity.of(new BigDecimal("400"),Unit.GRAM),List.of(b(2,"300",Unit.GRAM,LocalDate.of(2026,8,2)),b(1,"200",Unit.GRAM,LocalDate.of(2026,8,1)))); assertThat(p.allocations()).extracting(InventoryConsumptionAllocation::batchId).containsExactly(1L,2L); assertThat(p.allocations().get(1).amount()).isEqualByComparingTo("200");} @Test void rejectsInsufficientAndIncompatible(){assertThatThrownBy(()->new InventoryConsumptionAllocator().allocate(1,Quantity.of(new BigDecimal("400"),Unit.GRAM),List.of(b(1,"200",Unit.GRAM,null)))).isInstanceOf(InsufficientInventoryException.class); assertThat(new InventoryConsumptionAllocator().allocate(1,Quantity.of(new BigDecimal("2"),Unit.PIECE),List.of(b(1,"2",Unit.PIECE,null))).allocations()).hasSize(1);} @Test void consumesImmutably(){var x=b(1,"500",Unit.GRAM,null); var y=x.consume(Quantity.of(new BigDecimal("200"),Unit.GRAM)); assertThat(x.remainingQuantity().amount()).isEqualByComparingTo("500"); assertThat(y.remainingQuantity().amount()).isEqualByComparingTo("300"); assertThat(y.version()).isEqualTo(1); assertThatThrownBy(()->x.consume(Quantity.of(new BigDecimal("600"),Unit.GRAM))).isInstanceOf(InvalidInventoryBatchException.class);} }
